package java_basics;

public class Area {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		//Circle
		int rad=3;
		double area_cir=3.14*rad*rad;
		System.out.println("Area of circle="+area_cir);
		
		//Triangle
		int base=10;
		int hei=5;
		double area_tri=0.5*base*hei;
		System.out.println("Area of triangle="+area_tri);
		
		//Rectangle
		int len=2;
		int bred=5;
		int area_rec=len*bred;
		System.out.println("Area of rectangle="+area_rec);
		
		//Square
		int side=6;
		int area_sqar=side*side;
		System.out.println("Area of square="+area_sqar);

	}

}
